"""Environment-variable interpolation for configuration trees."""
import re


class ConfigError(KeyError):
    pass


_VAR_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def _placeholder_end(value, start):
    """Find the end of a balanced placeholder, including nested defaults."""
    depth = 1
    index = start + 2
    while index < len(value):
        if value.startswith("${", index):
            depth += 1
            index += 2
        elif value[index] == "}":
            depth -= 1
            index += 1
            if depth == 0:
                return index
        else:
            index += 1
    return None


def _resolve_placeholder(expression, env):
    """Resolve the contents of one balanced placeholder."""
    if ":-" in expression:
        var, default = expression.split(":-", 1)
        if not _VAR_RE.fullmatch(var):
            return "${" + expression + "}"
        # Shell-style ``:-`` treats an unset or empty value as missing.
        if env.get(var):
            return str(env[var])
        return interpolate_str(default, env)

    if not _VAR_RE.fullmatch(expression):
        return "${" + expression + "}"
    if expression not in env:
        raise ConfigError(expression)
    return str(env[expression])


def interpolate_str(value, env):
    """Substitute ${VAR} / ${VAR:-default} references in a single string."""
    result = []
    index = 0
    while index < len(value):
        start = value.find("${", index)
        if start == -1:
            result.append(value[index:])
            break
        result.append(value[index:start])
        end = _placeholder_end(value, start)
        if end is None:
            result.append(value[start:])
            break
        result.append(_resolve_placeholder(value[start + 2:end - 1], env))
        index = end
    return "".join(result)


def interpolate_tree(node, env):
    """Recursively interpolate every string inside dicts/lists/trees."""
    if isinstance(node, str):
        return interpolate_str(node, env)
    if isinstance(node, dict):
        return {key: interpolate_tree(value, env) for key, value in node.items()}
    if isinstance(node, list):
        return [interpolate_tree(item, env) for item in node]
    return node

