"""Deep merge for layered configuration dictionaries."""


def deep_merge(base, override, array_strategy="replace"):
    """Merge ``override`` into ``base`` recursively.

    Dicts merge recursively. Arrays follow ``array_strategy``:
    ``"replace"`` keeps the override list, ``"append"`` concatenates
    base + override.
    """
    result = dict(base)
    for key, value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(value, dict):
            result[key] = deep_merge(result[key], value, array_strategy=array_strategy)
        elif key in result and isinstance(result[key], list) and isinstance(value, list):
            if array_strategy == "append":
                result[key] = list(result[key]) + list(value)
            else:
                result[key] = list(value)
        else:
            result[key] = value
    return result

